#!/usr/bin/env python3
"""Self-contained delivery HTML from actual, hash-bound fixture screenshots."""
from pathlib import Path
import base64,hashlib,html,json
root=Path(__file__).resolve().parents[1]
out=root.parent/'deliverables';out.mkdir(exist_ok=True)
version=(root/'VERSION').read_text().strip()
iteration=version.rsplit('.',1)[-1]
h=lambda b:hashlib.sha256(b).hexdigest()
capture=json.loads((root/'validation/ui-capture.json').read_text())
assert capture['version']==version,'Recapture UI for this version'
for name,digest in capture['assets'].items():assert h((root/name).read_bytes())==digest,'Stale UI screenshot: '+name
for name,digest in capture['screenshots'].items():assert h((root/'validation'/name).read_bytes())==digest,'Screenshot changed: '+name
validation=json.loads((root/f'docs/VALIDATION-{iteration}.json').read_text())
assert validation['version']==version
probe=json.loads((root/f'validation/iteration-{iteration}/binary-probe.json').read_text())
binary_hash=h((root/'artifacts/workbuddy.so').read_bytes())
assert probe['result']=='PASS' and probe['binary_sha256']==binary_hash

def image(name):return 'data:image/png;base64,'+base64.b64encode((root/'validation'/name).read_bytes()).decode()
def figure(name,title,caption,cls=''):
 return f'<figure class="{cls}"><button class="shot" aria-label="放大：{html.escape(title)}"><img src="{image(name)}" alt="{html.escape(title)}；插件实际页面截图，使用本地模拟数据"><span>查看完整截图 ↗</span></button><figcaption><b>{html.escape(title)}</b><p>{html.escape(caption)}</p></figcaption></figure>'
